// Normalise le payload Twilio (form) ou Meta (JSON) en { from, to, text }.
const b = $json.body || {};

// Format Twilio : application/x-www-form-urlencoded
//   { From: 'whatsapp:+33612...', To: 'whatsapp:+14155...', Body: 'message' }
if (b.From && b.Body !== undefined) {
  return [{ json: {
    provider: 'twilio',
    from: String(b.From || '').replace(/^whatsapp:/, ''),
    to:   String(b.To   || '').replace(/^whatsapp:/, ''),
    text: String(b.Body || ''),
    msg_id: String(b.MessageSid || ''),
    raw: b
  } }];
}

// Format Meta WhatsApp Cloud API : JSON imbriqué
//   { entry:[{ changes:[{ value:{ messages:[{ from, text:{body} }], metadata:{display_phone_number} }] }] }] }
try {
  const v = (((b.entry || [])[0] || {}).changes || [])[0]?.value || {};
  const msg = (v.messages || [])[0];
  if (msg && msg.from) {
    return [{ json: {
      provider: 'meta',
      from: String(msg.from || ''),
      to:   String((v.metadata || {}).display_phone_number || ''),
      text: String((msg.text || {}).body || msg.button?.text || ''),
      msg_id: String(msg.id || ''),
      raw: b
    } }];
  }
} catch (e) {}

// Format inconnu — log et acquitte 200 pour ne pas faire échouer le provider
return [{ json: { provider: 'unknown', from: '', to: '', text: '', msg_id: '', raw: b } }];

// Auth par numéro : whitelist via team_members.whatsapp_number.
const inp = $('Normalize payload').first().json;
const from = String(inp.from || '').replace(/[^0-9+]/g, '');
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const toBool = v => v === true || String(v).toLowerCase() === 'true' || String(v) === '1';
const norm = s => String(s||'').replace(/[^0-9+]/g, '');
const me = rows.find(r => toBool(r.is_active) && norm(r.whatsapp_number) && norm(r.whatsapp_number) === from);

if (!me) {
  return [{ json: {
    _ok: false, _status: 403, _error: 'unauthorized_number',
    log: { from, intent: 'auth_failed', raw_message: inp.text, response: 'Numéro non autorisé.', status: 'denied' }
  } }];
}

// Parse intent : commande commençant par /
const text = String(inp.text || '').trim();
let intent = 'help', args = {};
if (text.startsWith('/')) {
  const parts = text.split(/\s+/);
  intent = (parts[0] || '/help').slice(1).toLowerCase();
  const rest = text.slice(parts[0].length).trim();
  if (intent === 'decide') {
    // /decide bcl_42 approve|reject [reason]
    const m = rest.match(/^(\S+)\s+(\S+)(?:\s+(.*))?$/);
    if (m) args = { id: m[1], decision: m[2].toLowerCase(), reason: m[3] || '' };
  } else if (intent === 'comment') {
    // /comment bcl_42 message
    const m = rest.match(/^(\S+)\s+(.+)$/s);
    if (m) args = { id: m[1], body: m[2] };
  } else if (intent === 'expense' || intent === 'income') {
    // /expense 25 vercel pro hosting
    const m = rest.match(/^(\d+(?:[.,]\d+)?)\s+(.+)$/);
    if (m) args = { amount: Number(m[1].replace(',', '.')), description: m[2] };
  } else if (intent === 'pending' || intent === 'balance' || intent === 'help' || intent === 'wishlist') {
    args = {};
  } else {
    intent = 'help';
  }
} else {
  intent = 'help';
}

return [{ json: {
  _ok: true,
  member: { id: me.id, name: me.name, role: me.role },
  from, intent, args,
  raw_message: text,
  msg_id: inp.msg_id,
  provider: inp.provider
} }];

// Routage intent → réponse texte. Lecture seule pour l'instant
// (les intents qui muteraient appellent les autres workflows par HTTP en V2).
const inp = $('Auth & parse intent').first().json;
const { intent, args, member } = inp;

let reply = '';
let status = 'replied';

if (intent === 'help') {
  reply = `Symbalyx Bot — commandes:\n\n` +
          `/balance — solde et runway\n` +
          `/pending — décisions à valider\n` +
          `/wishlist — achats envisagés\n` +
          `/decide ID approve|reject [raison]\n` +
          `/comment ID message\n` +
          `/expense MONTANT description\n` +
          `/income  MONTANT description\n\n` +
          `Ex: /decide bcl_42 approve fit niche`;
} else if (intent === 'balance') {
  // En V1 (skeleton), réponse statique.
  // En V2, appel HTTP vers WF20 GET /symbalyx-finance pour récupérer l'état.
  reply = `Bonjour ${member.name}.\n\n` +
          `Pour activer cette commande, branche WF30 → WF20 (HTTP Request node "GET /symbalyx-finance") et reformate la réponse ici.`;
  status = 'stub';
} else if (intent === 'pending') {
  reply = `Pour activer cette commande, lis business_control où decision_status=pending et liste les 5 plus prioritaires.`;
  status = 'stub';
} else if (intent === 'wishlist') {
  reply = `Pour activer cette commande, lis wishlist où decided=pending et formate par priorité.`;
  status = 'stub';
} else if (intent === 'decide') {
  if (!args.id || !args.decision || !['approve','approved','reject','rejected','escalate'].includes(args.decision)) {
    reply = `Format: /decide ID approve|reject [raison]`; status = 'invalid';
  } else {
    reply = `Pour activer cette commande, fais un HTTP POST vers /webhook/symbalyx-decision avec { bcl_id:"${args.id}", decision:"${args.decision === 'approve' ? 'approved' : args.decision === 'reject' ? 'rejected' : args.decision}", decided_by:"${member.name}", decider_id:"${member.id}", reason:"${(args.reason||'').replace(/"/g,'\\"')}" }`;
    status = 'stub';
  }
} else if (intent === 'comment') {
  if (!args.id || !args.body) { reply = `Format: /comment ID message`; status = 'invalid'; }
  else {
    reply = `Pour activer, POST /webhook/symbalyx-comments avec { item_type, item_id:"${args.id}", author:"${member.name}", author_id:"${member.id}", body:"${args.body.replace(/"/g,'\\"')}" }`;
    status = 'stub';
  }
} else if (intent === 'expense' || intent === 'income') {
  if (!args.amount || !args.description) { reply = `Format: /${intent} MONTANT description`; status = 'invalid'; }
  else {
    reply = `Pour activer, POST /webhook/symbalyx-finance avec { kind:"ledger", row:{ type:"${intent}", amount:${args.amount}, description:"${args.description.replace(/"/g,'\\"')}", status:"done", created_by:"${member.name}", created_by_id:"${member.id}" } }`;
    status = 'stub';
  }
}

return [{ json: {
  ...inp,
  reply,
  status,
  log: {
    id: 'wa_' + Date.now(),
    ts: new Date().toISOString(),
    direction: 'inbound',
    from_number: inp.from,
    to_number: '',
    member_id: member.id,
    intent,
    raw_message: inp.raw_message,
    parsed_args: JSON.stringify(args),
    response: reply,
    status,
    error: '',
    trace_id: inp.msg_id || ''
  }
} }];
